using System;

namespace Jellyfin.Plugin.Exporter.Models;

/// <summary>
/// A named export preset configured in the plugin settings.
/// </summary>
public class ExportProfile
{
    /// <summary>
    /// Gets or sets the profile id. Generated by the settings page for new
    /// profiles and stable for the lifetime of the profile.
    /// </summary>
    public Guid Id { get; set; } = Guid.NewGuid();

    /// <summary>
    /// Gets or sets the operator-visible name. Unique and non-empty.
    /// </summary>
    public string Name { get; set; } = string.Empty;

    /// <summary>
    /// Gets or sets the target codec.
    /// </summary>
    public ExportFormat Format { get; set; } = ExportFormat.H264;

    /// <summary>
    /// Gets or sets the target resolution.
    /// </summary>
    public ExportResolution Resolution { get; set; } = ExportResolution.Resolution1080p;

    /// <summary>
    /// Gets or sets the audio channel handling.
    /// </summary>
    public ExportAudioChannels AudioChannels { get; set; } = ExportAudioChannels.Original;

    /// <summary>
    /// Gets or sets the absolute output directory. The exporter creates the
    /// Movies/ and TV/ trees underneath it.
    /// </summary>
    public string OutputDirectory { get; set; } = string.Empty;

    /// <summary>
    /// Gets or sets a value indicating whether the profile may be used to
    /// enqueue new jobs. Running jobs are unaffected.
    /// </summary>
    public bool Enabled { get; set; } = true;

    /// <summary>
    /// Gets or sets a value indicating whether exports with this profile
    /// honour Jellyfin's own transcoding settings (Dashboard &gt; Playback):
    /// the hardware-encoding switch, the allowed HEVC/AV1 codecs, the encoder
    /// preset, the H.264/H.265 CRF and the encoding thread count. Defaults to
    /// true; when false the plugin's own encoder settings apply, exactly as
    /// before this option existed.
    /// </summary>
    public bool UseJellyfinTranscodingSettings { get; set; } = true;
}
